import { FunctionalComponent } from 'preact';
import cn from 'classnames';

import { getFaviconUrl } from '../../slice/selectors/suggestions/utils';
import { SearchTag } from '../../slice/types';

import styles from './styles.module.scss';

interface Props {
  isActive: boolean,
  searchTags: SearchTag[],
  choosen: SearchTag,
  onClick: (b: SearchTag) => unknown,
}

const SearchTags: FunctionalComponent<Props> = ({ isActive, searchTags, choosen, onClick }: Props) => {
  const handleClick = (searchTag) => (evt) => {
    evt.preventDefault();
    onClick(searchTag);
  }

  return (
    <div className={cn(styles.container, (isActive && searchTags.length) && styles.active)}>
      <b className={styles.label}>Search in</b>
      {searchTags.map((searchTag) => (
        <button
          key={searchTag.u}
          onClick={handleClick(searchTag)}
          className={cn(styles.element, choosen?.u === searchTag.u && styles.active)}
          type="button"
        >
          <img
            className={styles.favicon}
            src={getFaviconUrl(searchTag.u)}
            alt=""
            height={14}
            width={14}
          />
          {searchTag.s}
        </button>
      ))}
    </div>
  )
};

export default SearchTags;