import { FunctionComponent} from 'preact';
import { useDispatch } from 'react-redux';
import cn from 'classnames';

import FavoriteIcon from '@material-ui/icons/Favorite';

import MoreButton from '../../../../shared/MoreButton';
import styles from './../styles.module.scss';
import { clickedAd } from '../slice';
import { AdTile as AdTileType } from '../slice/types';

interface AdTileProps {
  item: AdTileType;
  onClickMore: () => void;
  isGlowing: boolean;
}

const AdTile: FunctionComponent<AdTileProps> = ({
  item,
  onClickMore,
  isGlowing,
}: AdTileProps) => {
  const dispatch = useDispatch();
  const onClick = (): void => {
    dispatch(clickedAd(item));
  };

  return (
    <div className={cn(styles.topPageContainer, styles.topPageContainerAd, isGlowing ? styles.glow : '')}>
      <MoreButton className={styles.moreButton} onClick={onClickMore} />
      <a className={styles.topPage} href={item.url} onClick={onClick}>
        <div className={cn(styles.hearts, styles.left)}>
          <FavoriteIcon />
          <FavoriteIcon />
          <FavoriteIcon />
          <FavoriteIcon />
        </div>
        <img src={item.impression_url} className={styles.adImpression} alt="" />
        <div className={cn(styles.icon, styles.adIcon, item.provider === 'zeropark' && styles.smallIcon)}>
          {item.image_url && <img src={item.image_url} alt="" />}
        </div>
        <span className={cn(styles.label, styles.adLabel)}>
          {item.title} <span className={styles.adInfo}>· Ad</span>
        </span>
        <div className={cn(styles.hearts, styles.right)}>
          <FavoriteIcon />
          <FavoriteIcon />
          <FavoriteIcon />
          <FavoriteIcon />
        </div>
      </a>
    </div>
  );
};

export default AdTile;
